class Solution {
public:
    long long minCost(std::vector<int>& nums, std::vector<int>& costs) {
        int n = nums.size();
        std::vector<long long> dp(n, 1e18);
        dp[0] = 0;
        std::vector<int> stk_ge, stk_lt;
        for (int i = 0; i < n; ++i) {
            while (!stk_ge.empty() && nums[i] >= nums[stk_ge.back()]) {
                int prev = stk_ge.back(); stk_ge.pop_back();
                dp[i] = std::min(dp[i], dp[prev] + costs[i]);
            }
            stk_ge.push_back(i);
            while (!stk_lt.empty() && nums[i] < nums[stk_lt.back()]) {
                int prev = stk_lt.back(); stk_lt.pop_back();
                dp[i] = std::min(dp[i], dp[prev] + costs[i]);
            }
            stk_lt.push_back(i);
        }
        return dp[n - 1];
    }
};

class Solution {
    public long minCost(int[] nums, int[] costs) {
        int n = nums.length;
        long[] dp = new long[n];
        java.util.Arrays.fill(dp, Long.MAX_VALUE / 2);
        dp[0] = 0;
        int[] stkGe = new int[n];
        int[] stkLt = new int[n];
        int topGe = -1, topLt = -1;
        for (int i = 0; i < n; i++) {
            while (topGe >= 0 && nums[i] >= nums[stkGe[topGe]]) {
                int prev = stkGe[topGe--];
                dp[i] = Math.min(dp[i], dp[prev] + costs[i]);
            }
            stkGe[++topGe] = i;
            while (topLt >= 0 && nums[i] < nums[stkLt[topLt]]) {
                int prev = stkLt[topLt--];
                dp[i] = Math.min(dp[i], dp[prev] + costs[i]);
            }
            stkLt[++topLt] = i;
        }
        return dp[n - 1];
    }
}

var minCost = function(nums, costs) {
    const n = nums.length;
    const dp = new Float64Array(n).fill(Infinity);
    dp[0] = 0;
    const stkGe = [];
    const stkLt = [];
    for (let i = 0; i < n; i++) {
        while (stkGe.length > 0 && nums[i] >= nums[stkGe[stkGe.length - 1]]) {
            const prev = stkGe.pop();
            if (dp[prev] + costs[i] < dp[i]) dp[i] = dp[prev] + costs[i];
        }
        stkGe.push(i);
        while (stkLt.length > 0 && nums[i] < nums[stkLt[stkLt.length - 1]]) {
            const prev = stkLt.pop();
            if (dp[prev] + costs[i] < dp[i]) dp[i] = dp[prev] + costs[i];
        }
        stkLt.push(i);
    }
    return dp[n - 1];
};
